// Get array from path const s_expr_param_t* array = se_dicts_get_array(dict, mod_def, "zones"); if (!array) return; // Get array element count uint16_t count = se_dicts_array_count(array); printf("Array has %d elements
", count); // Iterate array elements se_arrays_iter_t iter; se_arrays_iter_init(&iter, array); const s_expr_param_t* value; uint16_t index; while (se_arrays_iter_next(&iter, &value, &index)) { // value points to current element // index is 0-based position uint8_t opcode = value->type & S_EXPR_OPCODE_MASK; if (opcode == S_EXPR_PARAM_INT) { printf("[%d] = %d
", index, (int)value->int_val); } else if (opcode == S_EXPR_PARAM_OPEN_DICT) { // Element is a nested dictionary - can navigate further ct_int_t id = se_dicts_get_int(value, mod_def, "id", -1); printf("[%d].id = %d
", index, (int)id); } } // Reset iterator to start over se_arrays_iter_reset(&iter);
